import z3
import time
import itertools

n = 19
min_edges = 32

def solve_for_partition(a, b, c):
    assert a + b + c == n
    # Color classes
    V0 = list(range(0, a))
    V1 = list(range(a, a+b))
    V2 = list(range(a+b, n))

    parts = [V0, V1, V2]
    part_id = {}
    for pi, Vi in enumerate(parts):
        for v in Vi:
            part_id[v] = pi

    # Edge variables (only between different parts)
    edge_vars = {}
    for pi, Vi in enumerate(parts):
        for pj, Vj in enumerate(parts):
            if pi < pj:
                for u in Vi:
                    for v in Vj:
                        edge_vars[(u,v)] = z3.Bool(f"e_{u}_{v}")

    s = z3.Solver()
    s.set("timeout", 120000)  # 120 seconds

    print(f"Edge vars count: {len(edge_vars)}")

    # No C_4 constraints
    c4_count = 0
    for pi, Vi in enumerate(parts):
        for u_idx in range(len(Vi)):
            for v_idx in range(u_idx+1, len(Vi)):
                uu, vv = Vi[u_idx], Vi[v_idx]
                for pj, Vj in enumerate(parts):
                    if pi == pj:
                        continue
                    for x_idx in range(len(Vj)):
                        for y_idx in range(x_idx+1, len(Vj)):
                            xx, yy = Vj[x_idx], Vj[y_idx]
                            # Cannot have both u and v connected to both x and y
                            e_ux = edge_vars.get((min(uu,xx), max(uu,xx)))
                            e_uy = edge_vars.get((min(uu,yy), max(uu,yy)))
                            e_vx = edge_vars.get((min(vv,xx), max(vv,xx)))
                            e_vy = edge_vars.get((min(vv,yy), max(vv,yy)))
                            if e_ux is not None and e_uy is not None and e_vx is not None and e_vy is not None:
                                s.add(z3.Not(z3.And(e_ux, e_uy, e_vx, e_vy)))
                                c4_count += 1
    print(f"C4 constraints: {c4_count}")

    # 5-cycle constraints
    def all_k_cycles_fast(verts):
        k = len(verts)
        cycles = []
        seen = set()
        for perm in itertools.permutations(verts):
            min_idx = perm.index(min(perm))
            rotated = perm[min_idx:] + perm[:min_idx]
            rev = (rotated[0],) + tuple(reversed(rotated[1:]))
            if rotated < rev:
                canon = rotated
            else:
                canon = rev
            if canon not in seen:
                seen.add(canon)
                cycles.append(rotated)
        return cycles

    print(f"Adding 5-cycle constraints...")
    c5_count = 0
    for combo in itertools.combinations(range(n), 5):
        for cycle in all_k_cycles_fast(combo):
            edges_cycle = []
            ok = True
            for i in range(5):
                x, y = cycle[i], cycle[(i+1)%5]
                e = edge_vars.get((min(x,y), max(x,y)))
                if e is None:
                    ok = False
                    break
                edges_cycle.append(e)
            if not ok:
                continue
            s.add(z3.Not(z3.And(*edges_cycle)))
            c5_count += 1
    print(f"C5 constraints: {c5_count}")

    # 6-cycle constraints
    print(f"Adding 6-cycle constraints...")
    c6_count = 0
    for combo in itertools.combinations(range(n), 6):
        for cycle in all_k_cycles_fast(combo):
            edges_cycle = []
            ok = True
            for i in range(6):
                x, y = cycle[i], cycle[(i+1)%6]
                e = edge_vars.get((min(x,y), max(x,y)))
                if e is None:
                    ok = False
                    break
                edges_cycle.append(e)
            if not ok:
                continue
            s.add(z3.Not(z3.And(*edges_cycle)))
            c6_count += 1
    print(f"C6 constraints: {c6_count}")

    # Edge count
    edge_sum = z3.Sum([z3.If(e, 1, 0) for e in edge_vars.values()])
    s.add(edge_sum >= min_edges)

    print(f"Solving for partition {a},{b},{c}...")
    start = time.time()
    result = s.check()
    elapsed = time.time() - start
    print(f"Result: {result}, time: {elapsed:.2f}s")

    if result == z3.sat:
        model = s.model()
        edge_list = []
        for (u,v), e in edge_vars.items():
            if z3.is_true(model.evaluate(e)):
                edge_list.append((u,v))
        return edge_list
    return None

